import{_ as t,o as a,c as o,a4 as r}from"./chunks/framework.ClGzHnIj.js";const u=JSON.parse('{"title":"GPU map","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/en/guide/gpu-map.html"}]]},"headers":[],"relativePath":"en/guide/gpu-map.md","filePath":"en/guide/gpu-map.md","lastUpdated":1792799313000}'),s={name:"en/guide/gpu-map.md"};function n(i,e,h,l,d,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="gpu-map" tabindex="-1">GPU map <a class="header-anchor" href="#gpu-map" aria-label="Permalink to &quot;GPU map&quot;">​</a></h1><p>The <strong>GPU map</strong> shows what sits in video memory right now, model by model, what each one&#39;s context costs on top of its weights, what is free, and which of your other models would fit.</p><p><strong>Sidebar item:</strong> GPU map (below Shared box) <strong>Route:</strong> <code>/gpu</code><strong>Added in:</strong> v0.8.0 (October 2026) <strong>Requires:</strong> nothing extra. It reads Ollama&#39;s own report of loaded models every few seconds. The card&#39;s memory size comes from the NVIDIA driver on Windows and Linux, and from the system on macOS.</p><h2 id="what-s-the-point" tabindex="-1">What&#39;s the point? <a class="header-anchor" href="#what-s-the-point" aria-label="Permalink to &quot;What&#39;s the point?&quot;">​</a></h2><p>&quot;Will it fit&quot; is the question in every local-model thread, and the answer is usually a number from <code>nvidia-smi</code> that nobody can read. The map draws it.</p><h2 id="the-bar" tabindex="-1">The bar <a class="header-anchor" href="#the-bar" aria-label="Permalink to &quot;The bar&quot;">​</a></h2><p>One bar, the width of the card&#39;s video memory. A block per loaded model, split in two: the weights, and dimmer, what the context and working buffers cost on top. Then the free space. Hover any block for its size.</p><p>Under the bar, each loaded model with its size, its quantisation, the context it is loaded with, and when the daemon will unload it unless it is used again. A model that did not fit shows how much of it runs from system RAM instead, which is why it is slow.</p><h2 id="when-ollama-s-figure-cannot-be-true" tabindex="-1">When Ollama&#39;s figure cannot be true <a class="header-anchor" href="#when-ollama-s-figure-cannot-be-true" aria-label="Permalink to &quot;When Ollama&#39;s figure cannot be true&quot;">​</a></h2><p>Ollama 0.40.6 to 0.40.10 under-report memory on its llama.cpp runner: it can report 432 MB for a gemma4 whose file is 6.1 GB, while the card holds 9 GB (<a href="https://github.com/ollama/ollama/issues/19089" target="_blank" rel="noreferrer">ollama#19089</a>). A loaded model cannot take less than its own file, so when Ollama reports under half of it, the map does not draw that figure. It uses the file size instead, says so under the model with what Ollama reported, and leaves the context&#39;s share out because it is not known. The verdicts below are judged against the corrected figure. The MCP tools <code>list_local_models</code> and <code>estimate_my_prompt</code> add the same sentence for agents.</p><h2 id="what-else-would-fit" tabindex="-1">What else would fit <a class="header-anchor" href="#what-else-would-fit" aria-label="Permalink to &quot;What else would fit&quot;">​</a></h2><p>Every pulled model that is not loaded, against the free space, with one of three verdicts:</p><ul><li><strong>fits now</strong>, next to what is loaded;</li><li><strong>fits only if what is loaded unloads first</strong>;</li><li><strong>larger than this card</strong>: it would run partly from system RAM.</li></ul><p>A model needs about 15% more than its file for a modest context; the verdicts allow for that.</p><h2 id="what-the-page-does-not-know" tabindex="-1">What the page does not know <a class="header-anchor" href="#what-the-page-does-not-know" aria-label="Permalink to &quot;What the page does not know&quot;">​</a></h2><p>How the daemon splits one model&#39;s footprint between weights and context. The weights are the file on disk; the rest is the context&#39;s cache and working buffers, so that split is an estimate. Free space is the card&#39;s memory minus what Ollama reports loaded; other programs using the GPU are not counted.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./system.html">My System</a> for the card and the driver.</li><li><a href="./shared-box.html">Shared box</a> for which tool reserved the context.</li></ul>',18)])])}const p=t(s,[["render",n]]);export{u as __pageData,p as default};
